#[inline]
fn destack_io_completion_wait_replay(
    context: &RuntimeCallContext,
    world: RuntimeWorld,
    out: *mut NativeArray<CompletionEvent>,
    handle: resource::CompletionHandle,
    timeoutns: u64,
    maxevents: u32,
) -> RuntimeResult<()> {
    let _ = (&handle, &timeoutns, &maxevents);

    context.replay().run_binding_with_payload_policy(
        IO_COMPLETION_WAIT,
        context.replay_payload_for(IO_COMPLETION_WAIT)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_io_completion_wait(
                    context, out, handle, timeoutns, maxevents,
                )
            },
            RuntimeWorld::Simulated => unsafe {
                platform_simulated_native::destack_io_completion_wait(
                    context, out, handle, timeoutns, maxevents,
                )
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value = unsafe {
                    if out.is_null() {
                        return Err(RuntimeError::from(PlatformError::null_pointer("out")).boxed());
                    }
                    *out
                };
                let result_recorded_raw = unsafe { result_value.as_slice()? };
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = *result_recorded_item_value;
                    let result_recorded_item_recorded_key = result_recorded_item.key;
                    let result_recorded_item_recorded_result = result_recorded_item.result;
                    let result_recorded_item_recorded_flags = result_recorded_item.flags;
                    let result_recorded_item_recorded = CompletionEvent {
                        key: result_recorded_item_recorded_key,
                        result: result_recorded_item_recorded_result,
                        flags: result_recorded_item_recorded_flags,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = IoCompletionWaitReplay {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(PlatformError::from(error.as_ref()));
                    IoCompletionWaitReplay { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut value_native_values = Vec::with_capacity(value.len());
                    for value_native_item in value {
                        let value_native_item_native_key = value_native_item.key;
                        let value_native_item_native_result = value_native_item.result;
                        let value_native_item_native_flags = value_native_item.flags;
                        let value_native_item_native = CompletionEvent {
                            key: value_native_item_native_key,
                            result: value_native_item_native_result,
                            flags: value_native_item_native_flags,
                        };
                        value_native_values.push(value_native_item_native);
                    }
                    let value_native = context.store_array(value_native_values);
                    unsafe {
                        std::ptr::write(out, value_native);
                    }
                    Ok(())
                }
                Err(error) => Err(RuntimeError::from(error).boxed()),
            }
        },
    )
}

